import java.io.*;
import java.util.*;

public class Main {
    static final InputStream is = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int rb() throws IOException {
        if (ptr == len) {
            len = is.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = rb();
        while (c != '-' && (c < '0' || c > '9')) c = rb();
        boolean neg = c == '-';
        if (neg) c = rb();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = rb();
        }
        return neg ? -r : r;
    }

    static long[] a, prefix;

    // Sum of distances from a[l..r) to its median.
    static long cost(int l, int r) {
        if (l == r) return 0;
        int m = (l + r) / 2;
        return a[m] * (m - l) - (prefix[m] - prefix[l]) + (prefix[r] - prefix[m + 1]) - a[m] * (r - m - 1);
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        Arrays.sort(a);
        prefix = new long[n + 1];
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + a[i];
        long best = Long.MAX_VALUE;
        for (int i = 0; i <= n; i++) best = Math.min(best, cost(0, i) + cost(i, n));
        System.out.println(best);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	c, _ := reader.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = reader.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = reader.ReadByte()
	}
	n := 0
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = reader.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	n := readInt()
	a := make([]int, n)
	for i := range a {
		a[i] = readInt()
	}
	sort.Ints(a)
	prefix := make([]int, n+1)
	for i, v := range a {
		prefix[i+1] = prefix[i] + v
	}
	// Sum of distances from a[l..r) to its median.
	cost := func(l, r int) int {
		if l == r {
			return 0
		}
		m := (l + r) / 2
		return a[m]*(m-l) - (prefix[m] - prefix[l]) + (prefix[r] - prefix[m+1]) - a[m]*(r-m-1)
	}
	best := -1
	for i := 0; i <= n; i++ {
		if c := cost(0, i) + cost(i, n); best < 0 || c < best {
			best = c
		}
	}
	fmt.Println(best)
}
